const loadMessages = async (otherUser, product = null) => {
    if (!user.user?.id || !otherUser?.id) {
        setError('Неверные данные пользователя');
        return;
    }

    setMessagesLoading(true);
    setError('');
    try {
        console.log('Загрузка сообщений для:', { 
            userId: user.user.id, 
            otherUserId: otherUser.id, 
            productId: product?.id 
        });
        
        const messages = await getMessages(user.user.id, otherUser.id, product?.id || null);
        console.log('Получено сообщений:', messages.length);
        message.setMessages(messages);
    } catch (error) {
        console.error('Ошибка при загрузке сообщений:', error);
        console.error('Детали ошибки:', error.response?.data);
        setError(`Не удалось загрузить сообщения: ${error.response?.data?.message || error.message}`);
    } finally {
        setMessagesLoading(false);
    }
};
